fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since arr.len() > 0 by assumption, it's safe to check consecutive pairs.
    // If any consecutive pair is out of order, the whole array isn't sorted.
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false;
        }
    }
    true
}

